/**
 * CoefficientVM — wraps a CoefficientM cell (alternativeId × propertyId).
 *
 * Exposes lower, modal, upper as read-write values. Editing any cell triggers
 * a re-solve via the onModelChanged callback.
 */
import { ComponentVMOf, MessageHub, NullDispatcher } from 'vmx';
import type { CoefficientM } from '../models/coefficient.js';

export type CoefficientVM = ComponentVMOf<CoefficientM>;

export function makeCoefficientVm(
  coefficient: CoefficientM,
  hub: MessageHub,
  onSolveTrigger: () => void,
): CoefficientVM {
  const vm = ComponentVMOf.builder<CoefficientM>()
    .name('coefficient')
    .model(coefficient)
    .services(hub, NullDispatcher.INSTANCE)
    .modeledHinter(
      (m) =>
        `(${m.alternativeId}, ${m.propertyId}): [${m.value.lower}, ${m.value.modal}, ${m.value.upper}]`,
    )
    .onModelChanged(() => {
      onSolveTrigger();
    })
    .build();
  vm.construct();
  return vm;
}

export interface DecisionM {
  readonly id: string;
  readonly name: string;
}

import type { TriangularFuzzyM } from './triangular-fuzzy.js';
import type { NormalizedFuzzyM } from './normalized-fuzzy.js';

export interface CriticalDecisionM {
  readonly decisionId: string;
  readonly triangularValue: TriangularFuzzyM;
  readonly normalizedValue: NormalizedFuzzyM;
  readonly score: number;
  readonly rank: number;
}

import type { TriangularFuzzyM } from './triangular-fuzzy.js';

export interface CoefficientM {
  readonly alternativeId: string;
  readonly propertyId: string;
  readonly value: TriangularFuzzyM;
}

/**
 * CriticalDecisionVM — read-only wrapper for a CriticalDecisionM.
 *
 * Created by ScenarioVM after each solve run. No mutations; no commands.
 */
import { ComponentVMOf, NullMessageHub, NullDispatcher } from 'vmx';
import type { CriticalDecisionM } from '../models/critical-decision.js';

export type CriticalDecisionVM = ComponentVMOf<CriticalDecisionM>;

export function makeCriticalDecisionVm(decision: CriticalDecisionM): CriticalDecisionVM {
  const vm = ComponentVMOf.builder<CriticalDecisionM>()
    .name('criticalDecision')
    .model(decision)
    .services(NullMessageHub.INSTANCE, NullDispatcher.INSTANCE)
    .modeledHinter((m) => `decisionId=${m.decisionId} rank=${m.rank}`)
    .build();
  vm.construct();
  return vm;
}

/**
 * DecisionVM — wraps a DecisionM.
 *
 * Observable: id (read-only), name (read-write).
 * Mutating name updates the underlying model but does NOT trigger a solve.
 */
import { ComponentVMOf, MessageHub, NullDispatcher } from 'vmx';
import type { DecisionM } from '../models/decision.js';

export type DecisionVM = ComponentVMOf<DecisionM>;

export function makeDecisionVm(decision: DecisionM, hub: MessageHub): DecisionVM {
  const vm = ComponentVMOf.builder<DecisionM>()
    .name('decision')
    .model(decision)
    .services(hub, NullDispatcher.INSTANCE)
    .modeledHinter((m) => m.name)
    .build();
  vm.construct();
  return vm;
}

"""CriticalDecisionVM — read-only wrapper for a CriticalDecisionM result.

Per spec/viewmodels.md §5.6: result VMs are read-only, no commands.
"""

from __future__ import annotations

from guidearch.models.critical_decision import CriticalDecisionM


class CriticalDecisionVM:
    """Read-only view-model wrapper for a ranked critical decision."""

    def __init__(self, model: CriticalDecisionM) -> None:
        self._model = model

    @property
    def decision_id(self) -> str:
        return self._model.decision_id

    @property
    def score(self) -> float:
        return self._model.score

    @property
    def rank(self) -> int:
        return self._model.rank

    @property
    def model(self) -> CriticalDecisionM:
        return self._model

"""CoefficientVM — wraps a CoefficientM (one cell in the alt x property grid).

Per spec/viewmodels.md §5.4:
  - Flat list CoefficientCellVM[] indexed by (alternativeId, propertyId).
  - Each cell exposes lower, modal, upper as read-write doubles.
  - Editing any cell triggers a solve.
"""

from __future__ import annotations

from dataclasses import replace

from vmx.components.component_vm import ComponentVMOf
from vmx.messages.protocols import Message
from vmx.services.dispatcher import Dispatcher
from vmx.services.message_hub import MessageHub

from guidearch.models.coefficient import CoefficientM
from guidearch.models.triangular_fuzzy import TriangularFuzzyM


class CoefficientVM(ComponentVMOf[CoefficientM]):
    """ViewModel for one (alternative, property) fuzzy coefficient cell.

    Exposes ``lower``, ``modal``, ``upper`` as read-write doubles.
    Any mutation emits PropertyChangedMessage("model") which ScenarioVM
    uses to trigger a re-solve.
    """

    def __init__(
        self,
        model: CoefficientM,
        hub: MessageHub[Message],
        dispatcher: Dispatcher,
    ) -> None:
        super().__init__(
            name=f"coefficient-vm-{model.alternative_id}-{model.property_id}",
            hint="",
            initial_model=model,
            modeled_hinter=lambda m: f"[{m.value.lower}, {m.value.modal}, {m.value.upper}]",
            on_model_changed=None,
            hub=hub,
            dispatcher=dispatcher,
        )

    # ── Observable properties ────────────────────────────────────────────────

    @property
    def alternative_id(self) -> str:
        return self.model.alternative_id

    @property
    def property_id(self) -> str:
        return self.model.property_id

    @property
    def lower(self) -> float:
        return self.model.value.lower

    @lower.setter
    def lower(self, value: float) -> None:
        old = self.model.value
        if old.lower != value:
            self.model = replace(
                self.model,
                value=TriangularFuzzyM(lower=value, modal=old.modal, upper=old.upper),
            )

    @property
    def modal(self) -> float:
        return self.model.value.modal

    @modal.setter
    def modal(self, value: float) -> None:
        old = self.model.value
        if old.modal != value:
            self.model = replace(
                self.model,
                value=TriangularFuzzyM(lower=old.lower, modal=value, upper=old.upper),
            )

    @property
    def upper(self) -> float:
        return self.model.value.upper

    @upper.setter
    def upper(self, value: float) -> None:
        old = self.model.value
        if old.upper != value:
            self.model = replace(
                self.model,
                value=TriangularFuzzyM(lower=old.lower, modal=old.modal, upper=value),
            )

/**
 * Critical decisions analysis — topsis.md §5.
 */
import type { ScenarioM } from '../scenario.js';
import type { CandidateM } from '../candidate.js';
import type { CriticalDecisionM } from '../critical-decision.js';
import { TriangularFuzzyM } from '../triangular-fuzzy.js';
import { altContribution, computeNormalizer, normalizeCandidates, solve, toZ } from './solve.js';

const TOP_N = 20; // topsis.md §8
const DECAY = 0.1; // topsis.md §8 — exp(-0.1 * rank)

/**
 * Rank decisions by how strongly they drive the top candidates' scores.
 *
 * Implements topsis.md §5. Aggregation is always 'max' (legacy hardcodes Max
 * here, ignoring config.aggregation — topsis.md §5 last paragraph).
 *
 * Returns decisions sorted by score ascending (lower = more critical).
 */
export function criticalDecisions(
  scenario: ScenarioM,
  candidates?: CandidateM[],
): CriticalDecisionM[] {
  const resolvedCandidates = candidates ?? solve(scenario);

  if (!resolvedCandidates.length) return [];

  // Take top-N ranked candidates
  const topN = resolvedCandidates.slice(0, Math.min(TOP_N, resolvedCandidates.length));

  // Build coeff lookup and normalizer
  const coeff = new Map<string, TriangularFuzzyM>();
  for (const c of scenario.coefficients) {
    coeff.set(`${c.alternativeId}|${c.propertyId}`, c.value);
  }
  const M = computeNormalizer(scenario);

  // Map decision_id → index in scenario.decisions
  const decIndex = new Map<string, number>(scenario.decisions.map((d, i) => [d.id, i]));

  // -------------------------------------------------------------------------
  // §5  contribution(di) = sum over c in Rt : exp(-0.1*rank(c)) * altContrib(c[i])
  // -------------------------------------------------------------------------
  const decContributions = new Map<string, TriangularFuzzyM>(
    scenario.decisions.map((d) => [d.id, TriangularFuzzyM.zero()]),
  );

  for (const c of topN) {
    const weightFactor = Math.exp(-DECAY * c.rank);
    for (const d of scenario.decisions) {
      const dIdx = decIndex.get(d.id)!;
      const altId = c.alternativeIds[dIdx];
      const ac = altContribution(altId, scenario, coeff, M);
      decContributions.set(d.id, decContributions.get(d.id)!.add(ac.mul(weightFactor)));
    }
  }

  // -------------------------------------------------------------------------
  // Convert to Z-space, compute PIS/NIS, normalize — same as §3.6-3.8
  // but over the *decision* set, with aggregation = max.
  // -------------------------------------------------------------------------
  const decisionIds = scenario.decisions.map((d) => d.id);
  const triangularValues = decisionIds.map((dId) => decContributions.get(dId)!);
  const zValues = triangularValues.map(toZ);

  if (!zValues.length) return [];

  // §3.7 + §3.8 over the *decision* set: identical pipeline to the candidate
  // path, just applied to per-decision contributions instead of per-candidate
  // totals. Reuse normalizeCandidates so a future tweak to the PIS/NIS math
  // stays in one place (matches the C# refactor in CriticalDecisions.Analyze).
  const normValues = normalizeCandidates(zValues);

  const weights = scenario.config.weights;

  // Score with max aggregation (legacy hardcodes Max here)
  const scoreMax = (n: { positive: number; average: number; negative: number }): number =>
    Math.max(
      weights.positive * n.positive,
      weights.average * n.average,
      weights.negative * n.negative,
    );

  const scores = normValues.map(scoreMax);

  // Sort ascending by score, tie-break by decisionId lexicographic
  const indexed = decisionIds.map((dId, i) => ({ i, dId }));
  indexed.sort((a, b) => {
    const diff = scores[a.i] - scores[b.i];
    if (diff !== 0) return diff;
    if (a.dId < b.dId) return -1;
    if (a.dId > b.dId) return 1;
    return 0;
  });

  return indexed.map(({ i, dId }, rank) => ({
    decisionId: dId,
    triangularValue: triangularValues[i],
    normalizedValue: normValues[i],
    score: scores[i],
    rank,
  }));
}

using GuideArch.Models;
using VMx.Components;
using VMx.Services;

namespace GuideArch.ViewModels;

/// <summary>
/// Factory for CriticalDecisionVM — read-only result wrapper for a
/// <see cref="CriticalDecisionM"/>. No commands. No mutation paths.
/// Per spec/viewmodels.md §5.6.
/// </summary>
public static class CriticalDecisionVMFactory
{
    public static ComponentVM<CriticalDecisionM> Create(CriticalDecisionM model)
    {
        var vm = ComponentVM<CriticalDecisionM>.Builder()
            .Name($"critical-decision-vm-rank{model.Rank}")
            .Model(model)
            .Services(NullMessageHub.Instance, NullDispatcher.Instance)
            .Build();
        vm.Construct();
        return vm;
    }
}

